-- Substitui os produtos placeholder pelo catalogo real do Stripe: cada linha e um
-- preco ja calculado (custo real DingConnect + margem + buffer de taxas Stripe,
-- ver metadata "cost_eur"/"margin_eur"/"fee_safe" nesses Price/Product no Stripe),
-- referenciado diretamente por stripe_price_id -- sem calculo de cambio no checkout.

ALTER TABLE airtime_products ADD COLUMN stripe_price_id VARCHAR(200);
ALTER TABLE airtime_products ADD COLUMN payer_amount_cents INTEGER;

-- Novas operadoras do Brasil presentes no catalogo Stripe mas ainda nao seedadas.
SELECT id, 'Sercomtel', 'SERCOMTEL_BR', 'https://imagerepo.ding.com/logo/7BF18C/BR.png', TRUE, '7BF18CBR', 10, 200 FROM countries WHERE iso_code = 'BR';
SELECT id, 'Algar MVNO', 'ALGARMVNO_BR', 'https://imagerepo.ding.com/logo/943DFA/BR.png', TRUE, '943DFABR', 10, 200 FROM countries WHERE iso_code = 'BR';

-- Remove pedidos de teste criados contra os produtos placeholder (pre-lancamento, sem
-- nenhum pagamento real associado -- apenas testes em modo Stripe test) para poder
-- substituir os produtos sem violar a foreign key.
DELETE FROM orders;

-- Remove os produtos placeholder (valores redondos ilustrativos) para todas as operadoras.
DELETE FROM airtime_products;

